    categories={
        {id="empathy",name="Verde · Empatía",color={.42,.75,.48,1},text="Escuchar, recordar y ofrecer apoyo. Sus efectos suelen favorecer la confianza y el compañerismo."},
        {id="humor",name="Amarillo / naranja · Humor",color={.96,.66,.25,1},text="Una broma puede aliviar la tensión o herir. Cambiar de tema puede evitar una conversación necesaria. Lee la frase de Rudy antes de confirmar."},
        {id="sincerity",name="Azul · Sinceridad",color={.40,.65,.94,1},text="Hablar con honestidad, reconocer errores y compartir dudas. Consulta la frase y el coste de cada carta."},
        {id="initiative",name="Violeta · Magia e iniciativa",color={.72,.48,.91,1},text="Investigar, proponer un plan y conjurar. Algunas cartas tienen una versión de combate; otras exigen compañía."},
